SourceCode.Declaration:
class TFMMediaProvider extends TFMCachedProvider
{
    private TFMMediaStore mediaStore;

}

Method.Source:
public static TFMMediaProvider instance()
{
    TFMMediaProvider provider;
    provider = TFMCachedProvider::getProviderInstance(classStr(TFMMediaProvider));
    return provider;
}

public anytype constructEntityImpl()
{
    mediaStore = new TFMMediaStore();
    return mediaStore;
}

public str getBase64ForMedia(str _mediaId)
{
    TFMMediaItem item = TFMMediaProvider::instance().getMedia(_mediaId);
    if(item && item.parmBase64())
    {
        return item.parmBase64();
    }
    return null;
}

public void setMedia(str _mediaId, str _base64, str _url)
{
    TFMMediaItem item = this.getEntityImpl().getMedia(_mediaId);
    if(!item)
    {
        item = new TFMMediaItem(_mediaId);
    }
    if(_base64)
    {
        item.parmBase64(_base64);
    }
    if(_url)
    {
        item.parmURL(_url);
    }
   //print strFmt('id: %1 base64: %2',_mediaId, _base64);
    this.getEntityImpl().addMedia(item);
}
